"""Standard-library CPU-only preview of RGB bytes generated by the existing common-picture formula."""
import pathlib, struct, sys, zlib
p = pathlib.Path(sys.argv[1])
font = {'C':['0111','1000','1000','1000','0111'],'P':['1110','1001','1110','1000','1000'],'U':['1001','1001','1001','1001','0110'],'D':['1110','1001','1001','1001','1110'],'R':['1110','1001','1110','1010','1001'],'A':['0110','1001','1111','1001','1001'],'F':['1111','1000','1110','1000','1000'],'T':['111','010','010','010','010'],'0':['0110','1001','1001','1001','0110'],'1':['010','110','010','010','111'],'5':['1111','1000','1110','0001','1110'],'.':['0','0','0','0','1'],' ':['00']*5}
def chunk(kind, data):
    return struct.pack('>I', len(data))+kind+data+struct.pack('>I', zlib.crc32(kind+data)&0xffffffff)
for fixture in ['mini-wave','gallery-sheet-4-slot-1']:
    width,height=3072,1064
    out=bytearray([255])*(width*height*3)
    for arm,strength in enumerate(['0','0.5','1']):
        raw=(p/(fixture+'-detail'+strength+'.rgb')).read_bytes()
        for y in range(1024): out[((y+40)*width+arm*1024)*3:((y+40)*width+arm*1024+1024)*3]=raw[y*3072:(y+1)*3072]
        cursor=arm*1024+16
        for char in 'CPU DRAFT '+strength:
            glyph=font[char]
            for y,row in enumerate(glyph):
                for x,bit in enumerate(row):
                    if bit=='1':
                        for sy in range(3):
                            for sx in range(3):
                                i=((10+y*3+sy)*width+cursor+x*3+sx)*3;out[i:i+3]=b'\0\0\0'
            cursor+=(len(glyph[0])+1)*3
    scan=b''.join(b'\0'+out[y*width*3:(y+1)*width*3] for y in range(height))
    png=b'\x89PNG\r\n\x1a\n'+chunk(b'IHDR',struct.pack('>IIBBBBB',width,height,8,2,0,0,0))+chunk(b'IDAT',zlib.compress(scan,6))+chunk(b'IEND',b'')
    (p/(fixture+'-CPU-draft.png')).write_bytes(png)
